from typing import List

class Solution:
    def findPattern(self, board: List[List[int]], pattern: List[str]) -> List[int]:
        R, C = len(board), len(board[0])
        r, c = len(pattern), len(pattern[0])

        for i in range(R - r + 1):
            for j in range(C - c + 1):
                tok_to_digit = {}   # pattern character -> board digit
                digit_to_tok = {}   # board digit -> pattern character
                ok = True
                for x in range(r):
                    for y in range(c):
                        tok = pattern[x][y]
                        d = board[i + x][j + y]
                        if tok.isdigit() and int(tok) != d:
                            ok = False
                            break
                        if tok in tok_to_digit:
                            if tok_to_digit[tok] != d:
                                ok = False
                                break
                        else:
                            if d in digit_to_tok:   # digit already claimed by another token
                                ok = False
                                break
                            tok_to_digit[tok] = d
                            digit_to_tok[d] = tok
                    if not ok:
                        break
                if ok:
                    return [i, j]
        return [-1, -1]
